<script setup lang="ts">
import { computed, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ChatDotRound, Document, FolderOpened, Lock, Menu, Plus, Setting, User } from '@element-plus/icons-vue'
import { useAuthStore } from './stores/auth'
const route = useRoute(); const router = useRouter(); const auth = useAuthStore(); const collapsed = ref(false)
const loggedIn = computed(() => auth.isAuthenticated)
const items = computed(() => [
  { label: 'Assistente', to: '/chat', icon: ChatDotRound, visible: true }, { label: 'Documentos', to: '/documents', icon: FolderOpened, visible: auth.hasAnyRole(['ADMIN', 'EDITOR']) },
  { label: 'Conflitos', to: '/conflicts', icon: Document, visible: auth.hasRole('ADMIN') }, { label: 'Usuários', to: '/users', icon: User, visible: auth.hasRole('ADMIN') },
])
function logout() { auth.logout(); router.push('/login') }
</script>
<template>
  <router-view v-if="!loggedIn" />
  <el-container v-else class="app-shell"><el-aside :width="collapsed ? '76px' : '250px'" class="sidebar">
    <div class="brand"><div class="brand-mark">R</div><span v-show="!collapsed">rag<span>kb</span></span></div><div v-show="!collapsed" class="workspace-label">BASE DE CONHECIMENTO</div>
    <el-menu :default-active="route.path" :collapse="collapsed" :collapse-transition="false" router class="nav-menu"><el-menu-item v-for="item in items.filter((entry) => entry.visible)" :key="item.to" :index="item.to"><el-icon><component :is="item.icon" /></el-icon><template #title>{{ item.label }}</template></el-menu-item></el-menu>
    <div class="sidebar-footer"><el-button text class="collapse-button" @click="collapsed = !collapsed"><el-icon><Menu /></el-icon><span v-show="!collapsed">Recolher menu</span></el-button></div>
  </el-aside><el-container><el-header class="topbar"><div class="environment"><span class="live-dot"></span> Ambiente corporativo</div><div class="top-actions"><el-button :icon="Plus" round class="new-query" @click="router.push('/chat')">Nova consulta</el-button><el-dropdown trigger="click"><button class="profile"><span>{{ auth.initials }}</span><div><b>{{ auth.username }}</b><small>{{ auth.roles.join(' · ') }}</small></div></button><template #dropdown><el-dropdown-menu><el-dropdown-item :icon="Setting">Preferências</el-dropdown-item><el-dropdown-item divided :icon="Lock" @click="logout">Sair da conta</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></el-header><el-main class="content"><router-view /></el-main></el-container></el-container>
</template>
